mkdir -p /app/output && cat > /app/output/styles.css <<'EOF'
:root {
  --navy: #0a1628;
  --navy-2: #10243c;
  --forest: #003f2d;
  --teal: #0d6f73;
  --gold: #c8a45d;
  --gold-2: #e4c982;
  --white: #ffffff;
  --stone-50: #f7f8f8;
  --stone-100: #eef1f2;
  --stone-200: #dfe5e7;
  --stone-500: #66727c;
  --stone-700: #33414f;
  --ink: #172130;
  --shadow: 0 24px 70px rgba(10, 22, 40, 0.16);
  --radius-sm: 10px;
  --radius: 18px;
  --radius-lg: 28px;
  --container: 1180px;
  --font: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --display: "Playfair Display", Georgia, serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--font);
  color: var(--ink);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
body.menu-open { overflow: hidden; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button, input { font: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 3px solid rgba(200, 164, 93, 0.65); outline-offset: 3px; }

.container { width: min(var(--container), calc(100% - 40px)); margin-inline: auto; }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 14px;
  color: var(--gold);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}
.eyebrow::before { content: ""; width: 34px; height: 1px; background: currentColor; }
h1, h2, h3, h4, p { margin-top: 0; }
h1, h2, .display {
  font-family: var(--display);
  line-height: 1.05;
  letter-spacing: -0.035em;
  color: var(--navy);
}
h1 { font-size: clamp(3rem, 8vw, 6.9rem); max-width: 980px; }
h2 { font-size: clamp(2.25rem, 5vw, 4.6rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.65rem); line-height: 1.2; color: var(--navy); }
p { color: var(--stone-700); }
.lede { font-size: clamp(1.08rem, 2vw, 1.35rem); color: #d9e2e6; max-width: 720px; }
.section { padding: clamp(70px, 9vw, 118px) 0; }
.section.tight { padding: clamp(46px, 7vw, 76px) 0; }
.section-head { display: flex; justify-content: space-between; gap: 30px; align-items: end; margin-bottom: 36px; }
.section-head p { max-width: 520px; margin-bottom: 8px; font-size: 1.05rem; }
.bg-soft { background: linear-gradient(180deg, var(--stone-50), #fff); }
.bg-navy { background: var(--navy); color: var(--white); }
.bg-navy h2, .bg-navy h3 { color: var(--white); }
.bg-navy p { color: #c8d3da; }

.btn {
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 13px 22px;
  font-weight: 800;
  font-size: 0.92rem;
  transition: transform .2s ease, background .2s ease, border-color .2s ease, color .2s ease;
}
.btn:hover { transform: translateY(-2px); }
.btn-primary { background: var(--gold); color: var(--navy); }
.btn-primary:hover { background: var(--gold-2); }
.btn-outline { border-color: rgba(255,255,255,.38); color: #fff; }
.btn-outline:hover { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.7); }
.btn-dark { background: var(--navy); color: #fff; }
.link-arrow { color: var(--forest); font-weight: 850; display: inline-flex; align-items: center; gap: 8px; }
.link-arrow::after { content: "→"; transition: transform .2s ease; }
.link-arrow:hover::after { transform: translateX(4px); }

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10, 22, 40, 0.94);
  color: var(--white);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid rgba(255,255,255,.1);
}
.navbar { height: 78px; display: flex; align-items: center; justify-content: space-between; gap: 22px; }
.logo { display: inline-flex; align-items: center; gap: 12px; font-weight: 900; letter-spacing: -.04em; font-size: 1.25rem; }
.logo-mark { width: 34px; height: 34px; border-radius: 8px; background: linear-gradient(135deg, var(--gold), #fff 48%, var(--teal)); box-shadow: inset 0 0 0 1px rgba(255,255,255,.25); }
.nav-links { display: flex; align-items: center; gap: 2px; }
.nav-link, .nav-trigger {
  color: rgba(255,255,255,.86);
  background: transparent;
  border: 0;
  min-height: 44px;
  padding: 12px 13px;
  border-radius: 999px;
  font-weight: 750;
  font-size: .91rem;
}
.nav-link:hover, .nav-trigger:hover, .nav-trigger[aria-expanded="true"] { color: #fff; background: rgba(255,255,255,.09); }
.header-actions { display: flex; align-items: center; gap: 12px; }
.search-btn, .menu-toggle {
  min-width: 44px;
  min-height: 44px;
  border: 1px solid rgba(255,255,255,.2);
  color: #fff;
  background: rgba(255,255,255,.06);
  border-radius: 999px;
}
.menu-toggle { display: none; }

.mega-menu {
  position: absolute;
  left: 50%;
  top: 78px;
  width: min(1080px, calc(100vw - 40px));
  transform: translateX(-50%) translateY(-8px);
  padding: 28px;
  border-radius: 0 0 26px 26px;
  background: rgba(255,255,255,.98);
  color: var(--ink);
  box-shadow: var(--shadow);
  border: 1px solid rgba(10,22,40,.08);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .18s ease, transform .18s ease, visibility .18s ease;
}
.mega-menu.open, .nav-item-services:hover .mega-menu, .nav-item-services:focus-within .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}
.mega-grid { display: grid; grid-template-columns: 1.45fr .8fr .7fr; gap: 28px; }
.mega-kicker { color: var(--forest); font-weight: 900; letter-spacing: .12em; font-size: .72rem; text-transform: uppercase; margin-bottom: 12px; }
.mega-list { display: grid; gap: 8px; }
.mega-card {
  display: grid;
  gap: 4px;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid transparent;
}
.mega-card:hover { background: var(--stone-50); border-color: var(--stone-200); }
.mega-card strong { color: var(--navy); }
.mega-card span { color: var(--stone-500); font-size: .88rem; }
.property-links { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.property-links a { padding: 12px; border: 1px solid var(--stone-200); border-radius: 12px; font-weight: 800; color: var(--navy); }
.property-links a:hover { border-color: var(--gold); color: var(--forest); }
.mega-feature { background: var(--navy); color: #fff; border-radius: 20px; padding: 24px; min-height: 100%; display: flex; flex-direction: column; justify-content: space-between; }
.mega-feature p { color: #cbd6dc; }

.mobile-panel { display: none; }

.hero {
  position: relative;
  min-height: 675px;
  display: flex;
  align-items: end;
  color: #fff;
  overflow: hidden;
  background: var(--navy);
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--hero-image), linear-gradient(135deg, #243448, #0a1628);
  background-size: cover;
  background-position: center;
  transform: scale(1.02);
}
.hero::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(10,22,40,.96) 0%, rgba(10,22,40,.72) 46%, rgba(10,22,40,.2) 100%), linear-gradient(0deg, rgba(10,22,40,.88), transparent 40%); }
.hero-content { position: relative; z-index: 1; padding: 120px 0 88px; }
.hero h1 { color: #fff; margin-bottom: 24px; }
.hero-actions { display: flex; gap: 14px; flex-wrap: wrap; margin-top: 34px; }
.hero-meta { display: flex; gap: 26px; flex-wrap: wrap; margin-top: 48px; border-top: 1px solid rgba(255,255,255,.18); padding-top: 24px; }
.hero-stat strong { display: block; color: #fff; font-size: 1.8rem; font-family: var(--display); }
.hero-stat span { color: #c7d1d9; font-size: .86rem; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; }
.page-hero { min-height: 520px; }
.page-hero h1 { max-width: 880px; }

.insight-strip { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--stone-200); box-shadow: var(--shadow); transform: translateY(-44px); position: relative; z-index: 5; }
.insight-mini { background: #fff; padding: 28px; min-height: 190px; display: flex; flex-direction: column; justify-content: space-between; }
.insight-mini span, .card-tag { color: var(--forest); font-size: .73rem; font-weight: 900; letter-spacing: .12em; text-transform: uppercase; }
.insight-mini h3 { margin: 14px 0 20px; }

.announcement { background: var(--forest); color: #fff; }
.announcement .container { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding-block: 30px; }
.announcement h2 { color: #fff; font-family: var(--font); font-size: clamp(1.35rem, 3vw, 2.1rem); letter-spacing: -.02em; margin: 0; }

.about-grid { display: grid; grid-template-columns: .9fr 1.25fr; gap: clamp(38px, 7vw, 92px); align-items: center; }
.arch-panel { min-height: 470px; border-radius: var(--radius-lg); overflow: hidden; background: linear-gradient(145deg, rgba(10,22,40,.25), rgba(0,63,45,.25)), var(--panel-image); background-size: cover; background-position: center; box-shadow: var(--shadow); }
.about-copy p { font-size: clamp(1.25rem, 2.4vw, 1.78rem); color: var(--navy); line-height: 1.42; }

.tabs-wrap { display: grid; grid-template-columns: 350px 1fr; gap: 32px; align-items: stretch; }
.tab-list { display: grid; gap: 12px; align-content: start; }
.tab-button {
  width: 100%;
  text-align: left;
  border: 1px solid var(--stone-200);
  background: #fff;
  border-radius: 16px;
  padding: 22px;
  min-height: 84px;
  color: var(--navy);
  font-weight: 900;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background .2s ease, color .2s ease, border-color .2s ease, transform .2s ease;
}
.tab-button:hover { transform: translateX(4px); }
.tab-button[aria-selected="true"] { background: var(--navy); color: #fff; border-color: var(--navy); }
.tab-panel {
  display: none;
  min-height: 440px;
  border-radius: var(--radius-lg);
  padding: clamp(30px, 5vw, 58px);
  color: #fff;
  background: linear-gradient(120deg, rgba(10,22,40,.94), rgba(0,63,45,.78)), var(--panel-image);
  background-size: cover;
  background-position: center;
  box-shadow: var(--shadow);
  animation: fadeSlide .28s ease;
}
.tab-panel.active { display: flex; flex-direction: column; justify-content: end; }
.tab-panel h3 { color: #fff; font-size: clamp(2rem, 4vw, 3.7rem); font-family: var(--display); letter-spacing: -.035em; max-width: 670px; }
.tab-panel p { color: #dbe5ea; font-size: 1.18rem; max-width: 650px; }
@keyframes fadeSlide { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.newsletter { background: linear-gradient(135deg, var(--navy), var(--forest)); color: #fff; border-radius: var(--radius-lg); padding: clamp(34px, 6vw, 58px); display: grid; grid-template-columns: 1fr auto; gap: 28px; align-items: center; overflow: hidden; position: relative; }
.newsletter::after { content: ""; position: absolute; width: 320px; height: 320px; border: 1px solid rgba(200,164,93,.36); border-radius: 50%; right: -90px; top: -100px; }
.newsletter h2 { color: #fff; margin-bottom: 10px; }
.newsletter p { color: #d4dee4; margin: 0; }
.newsletter form { position: relative; z-index: 1; display: flex; gap: 10px; min-width: min(100%, 440px); }
.newsletter input { width: 100%; min-height: 52px; border: 1px solid rgba(255,255,255,.18); border-radius: 999px; padding: 0 18px; background: rgba(255,255,255,.1); color: #fff; }
.newsletter input::placeholder { color: rgba(255,255,255,.65); }
.form-note { grid-column: 1 / -1; font-size: .9rem; color: #d5e0e5; min-height: 1.4em; }

.card-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; }
.card-grid.two { grid-template-columns: repeat(2, 1fr); }
.card-grid.four { grid-template-columns: repeat(4, 1fr); }
.info-card, .service-card, .insight-card, .commit-card {
  background: #fff;
  border: 1px solid var(--stone-200);
  border-radius: var(--radius);
  padding: 28px;
  min-height: 260px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}
.info-card:hover, .service-card:hover, .insight-card:hover, .commit-card:hover { transform: translateY(-5px); box-shadow: var(--shadow); border-color: rgba(200,164,93,.55); }
.service-card { min-height: 330px; }
.card-number { color: var(--gold); font-family: var(--display); font-size: 2.1rem; }
.insight-card { padding: 0; overflow: hidden; min-height: 430px; }
.insight-thumb { height: 190px; background: linear-gradient(135deg, rgba(10,22,40,.24), rgba(0,63,45,.2)), var(--thumb); background-size: cover; background-position: center; }
.insight-body { padding: 24px; display: flex; flex-direction: column; flex: 1; }
.insight-body time { color: var(--stone-500); font-size: .88rem; margin-top: auto; padding-top: 24px; }
.commit-card { min-height: 310px; }

.intro-statement { display: grid; grid-template-columns: .65fr 1.35fr; gap: 48px; align-items: start; }
.intro-statement p { font-size: clamp(1.15rem, 2vw, 1.55rem); color: var(--navy); line-height: 1.5; }
.capability-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.capability-card { background: #fff; border: 1px solid var(--stone-200); border-radius: var(--radius); padding: 28px; min-height: 285px; display: flex; flex-direction: column; justify-content: space-between; }
.capability-card:hover { border-color: var(--gold); box-shadow: var(--shadow); }
.capability-icon { width: 46px; height: 46px; border-radius: 14px; background: linear-gradient(135deg, rgba(200,164,93,.28), rgba(13,111,115,.16)); display: grid; place-items: center; color: var(--forest); font-weight: 950; margin-bottom: 18px; }

.split-feature { display: grid; grid-template-columns: 1fr .86fr; gap: 34px; align-items: stretch; }
.feature-panel { border-radius: var(--radius-lg); padding: clamp(30px, 5vw, 54px); background: var(--navy); color: #fff; min-height: 440px; display: flex; flex-direction: column; justify-content: space-between; }
.feature-panel p { color: #d5e0e7; }
.topic-sidebar { background: #fff; border: 1px solid var(--stone-200); border-radius: var(--radius-lg); padding: 34px; }
.topic-list { display: grid; gap: 10px; margin-top: 20px; }
.topic-list a { display: flex; justify-content: space-between; align-items: center; min-height: 56px; padding: 14px 0; border-bottom: 1px solid var(--stone-200); font-weight: 850; color: var(--navy); }
.topic-list a::after { content: "→"; color: var(--gold); }

.carousel { position: relative; overflow: hidden; border-radius: var(--radius-lg); background: var(--navy); color: #fff; }
.carousel-track { display: flex; transition: transform .32s ease; }
.carousel-slide { min-width: 100%; display: grid; grid-template-columns: 1fr .8fr; gap: 28px; padding: clamp(30px, 5vw, 58px); align-items: center; }
.carousel-slide p { color: #d5e1e7; }
.partner-visual { min-height: 280px; border-radius: 22px; background: linear-gradient(145deg, rgba(200,164,93,.28), rgba(13,111,115,.24)), var(--slide-image); background-size: cover; background-position: center; }
.carousel-controls { position: absolute; right: 24px; bottom: 24px; display: flex; gap: 10px; }
.carousel-controls button { width: 46px; height: 46px; border-radius: 50%; border: 1px solid rgba(255,255,255,.25); background: rgba(255,255,255,.1); color: #fff; }

.cta-band { border-radius: var(--radius-lg); padding: clamp(34px, 6vw, 62px); background: linear-gradient(135deg, var(--forest), var(--navy)); color: #fff; display: grid; grid-template-columns: 1fr auto; gap: 24px; align-items: center; }
.cta-band h2, .cta-band h3 { color: #fff; margin-bottom: 10px; }
.cta-band p { color: #dce7ea; margin-bottom: 0; }
.testimonial { border-left: 4px solid var(--gold); padding: 24px 0 24px 28px; max-width: 900px; }
.testimonial blockquote { margin: 0; font-family: var(--display); font-size: clamp(1.7rem, 4vw, 3.1rem); line-height: 1.18; color: var(--navy); letter-spacing: -.03em; }
.testimonial cite { display: block; margin-top: 18px; color: var(--stone-500); font-style: normal; font-weight: 800; }

.footer { background: #07101e; color: #fff; padding: 64px 0 30px; }
.footer-grid { display: grid; grid-template-columns: 1.2fr repeat(3, .7fr); gap: 34px; padding-bottom: 44px; border-bottom: 1px solid rgba(255,255,255,.12); }
.footer p { color: #b8c5ce; max-width: 360px; }
.footer h4 { color: #fff; margin-bottom: 14px; }
.footer a { display: block; color: #bdc9d1; padding: 6px 0; }
.footer a:hover { color: var(--gold); }
.footer-bottom { display: flex; justify-content: space-between; gap: 20px; flex-wrap: wrap; padding-top: 24px; color: #9aa9b3; font-size: .9rem; }
.footer-legal { display: flex; gap: 18px; flex-wrap: wrap; }

@media (max-width: 1040px) {
  .nav-links { display: none; }
  .menu-toggle { display: inline-grid; place-items: center; }
  .header-actions .btn { display: none; }
  .mobile-panel {
    position: fixed;
    inset: 78px 0 0;
    display: block;
    background: var(--navy);
    color: #fff;
    padding: 22px 20px 34px;
    transform: translateX(100%);
    transition: transform .24s ease;
    overflow-y: auto;
    z-index: 99;
  }
  .mobile-panel.open { transform: translateX(0); }
  .mobile-link, .mobile-accordion-trigger {
    width: 100%;
    min-height: 54px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border: 0;
    border-bottom: 1px solid rgba(255,255,255,.12);
    background: transparent;
    color: #fff;
    padding: 15px 0;
    font-weight: 850;
    text-align: left;
  }
  .mobile-accordion-panel { display: none; padding: 12px 0 18px 16px; border-bottom: 1px solid rgba(255,255,255,.12); }
  .mobile-accordion-panel.open { display: grid; gap: 8px; }
  .mobile-accordion-panel a { color: #d7e1e6; padding: 8px 0; }
  .tabs-wrap, .about-grid, .intro-statement, .split-feature, .carousel-slide { grid-template-columns: 1fr; }
  .card-grid.four, .capability-grid { grid-template-columns: repeat(2, 1fr); }
  .newsletter, .cta-band { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .container { width: min(100% - 28px, var(--container)); }
  .navbar { height: 70px; }
  .mobile-panel { inset-top: 70px; }
  .hero { min-height: 610px; }
  .hero-content { padding: 88px 0 62px; }
  .section-head { display: block; }
  .insight-strip, .card-grid, .card-grid.two, .card-grid.four, .capability-grid { grid-template-columns: 1fr; }
  .insight-strip { transform: none; margin-top: 0; box-shadow: none; }
  .announcement .container { align-items: flex-start; flex-direction: column; }
  .arch-panel { min-height: 340px; }
  .tab-panel { min-height: 380px; }
  .newsletter form { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { display: block; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: .01ms !important; }
}
EOF

cat > /app/output/script.js <<'EOF'
const servicesTrigger = document.querySelector('[data-services-trigger]');
const megaMenu = document.querySelector('[data-mega-menu]');
const menuToggle = document.querySelector('[data-menu-toggle]');
const mobilePanel = document.querySelector('[data-mobile-panel]');

function closeMega() {
  if (!servicesTrigger || !megaMenu) return;
  servicesTrigger.setAttribute('aria-expanded', 'false');
  megaMenu.classList.remove('open');
}

if (servicesTrigger && megaMenu) {
  servicesTrigger.addEventListener('click', (event) => {
    event.preventDefault();
    const isOpen = servicesTrigger.getAttribute('aria-expanded') === 'true';
    servicesTrigger.setAttribute('aria-expanded', String(!isOpen));
    megaMenu.classList.toggle('open', !isOpen);
  });

  document.addEventListener('click', (event) => {
    if (!event.target.closest('.nav-item-services')) closeMega();
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      closeMega();
      if (mobilePanel?.classList.contains('open')) toggleMobile(false);
    }
  });
}

function toggleMobile(force) {
  if (!menuToggle || !mobilePanel) return;
  const open = force ?? !mobilePanel.classList.contains('open');
  mobilePanel.classList.toggle('open', open);
  document.body.classList.toggle('menu-open', open);
  menuToggle.setAttribute('aria-expanded', String(open));
  menuToggle.textContent = open ? '×' : '☰';
}

if (menuToggle && mobilePanel) {
  menuToggle.addEventListener('click', () => toggleMobile());
  mobilePanel.addEventListener('click', (event) => {
    if (event.target.matches('a')) toggleMobile(false);
  });
}

document.querySelectorAll('[data-accordion-trigger]').forEach((trigger) => {
  trigger.addEventListener('click', () => {
    const panel = document.getElementById(trigger.getAttribute('aria-controls'));
    const isOpen = trigger.getAttribute('aria-expanded') === 'true';
    trigger.setAttribute('aria-expanded', String(!isOpen));
    panel?.classList.toggle('open', !isOpen);
  });
});

const tabButtons = document.querySelectorAll('[data-tab-target]');
const tabPanels = document.querySelectorAll('[data-tab-panel]');
tabButtons.forEach((button) => {
  button.addEventListener('click', () => {
    const target = button.dataset.tabTarget;
    tabButtons.forEach((item) => item.setAttribute('aria-selected', String(item === button)));
    tabPanels.forEach((panel) => panel.classList.toggle('active', panel.dataset.tabPanel === target));
  });
});

const newsletterForm = document.querySelector('[data-newsletter-form]');
if (newsletterForm) {
