        super().__init__(); self.links=[]; self.ids=set(); self.scripts=[]; self.css=[]
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if 'id' in attrs: self.ids.add(attrs['id'])
        if tag=='a' and attrs.get('href'): self.links.append(attrs['href'])
        if tag=='script' and attrs.get('src'): self.scripts.append(attrs['src'])
        if tag=='link' and attrs.get('href') and attrs.get('rel')== 'stylesheet': self.css.append(attrs['href'])
errors=[]
for p in root.glob('*.html'):
    parser=Parser(); parser.feed(p.read_text())
    for asset in parser.scripts+parser.css:
        if asset.startswith(('http','//')): continue
        if not (root/asset).exists(): errors.append(f'{p.name}: missing asset {asset}')
    for href in parser.links:
        if href.startswith(('http','mailto:','tel:')) or href == '#': continue
        path, frag = urldefrag(href)
        target = p.name if path == '' else path
        if target not in files:
            errors.append(f'{p.name}: broken link {href}')
        elif frag:
            target_parser=Parser(); target_parser.feed((root/target).read_text())
            if frag not in target_parser.ids:
